import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;
import org.apache.commons.text.StringEscapeUtils;

public class ReportServlet extends HttpServlet {

    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Custom filter - only allows alphanumeric and basic punctuation
    private String sanitizeForDisplay(String input) {
        if (input == null) return "";
        return input.replaceAll("[<>]", "");
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportId = req.getParameter("id");
        String format = req.getParameter("format");
        String callback = req.getParameter("callback");

        if (reportId == null || !reportId.matches("\\d+")) {
            resp.sendError(400, "Invalid report ID");
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            // Parameterized query - safe from SQLi
            PreparedStatement ps = conn.prepareStatement(
                "SELECT title, author, content, created_at FROM reports WHERE id = ? AND tenant_id = ?"
            );
            ps.setInt(1, Integer.parseInt(reportId));
            ps.setString(2, getTenantId(req));

            ResultSet rs = ps.executeQuery();
            if (!rs.next()) {
                resp.sendError(404, "Report not found");
                return;
            }

            String title = rs.getString("title");
            String author = rs.getString("author");
            String content = rs.getString("content");
            String createdAt = rs.getString("created_at");

            if ("jsonp".equals(format) && callback != null) {
                // JSONP endpoint for legacy dashboard widgets
                resp.setContentType("application/javascript");
                String json = String.format(
                    "{\"title\":\"%s\",\"author\":\"%s\",\"content\":\"%s\",\"created\":\"%s\"}",
                    StringEscapeUtils.escapeJson(title),
                    StringEscapeUtils.escapeJson(author),
                    StringEscapeUtils.escapeJson(content),
                    StringEscapeUtils.escapeJson(createdAt)
                );
                // callback is user-controlled - XSS via JSONP callback injection
                resp.getWriter().write(callback + "(" + json + ");");
            } else {
                resp.setContentType("text/html; charset=UTF-8");
                StringBuilder html = new StringBuilder();
                html.append("<!DOCTYPE html><html><head><title>");
                html.append(sanitizeForDisplay(title));
                html.append("</title></head><body>");
                html.append("<h1>").append(sanitizeForDisplay(title)).append("</h1>");
                html.append("<p>By: ").append(sanitizeForDisplay(author)).append("</p>");
                html.append("<div>").append(sanitizeForDisplay(content)).append("</div>");
                html.append("<footer>Created: ").append(sanitizeForDisplay(createdAt)).append("</footer>");
                html.append("</body></html>");
                resp.getWriter().write(html.toString());
            }

        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }

    private String getTenantId(HttpServletRequest req) {
        // Extracted from JWT by upstream auth filter
        return (String) req.getAttribute("x-tenant-id");
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Report creation endpoint
        String title = req.getParameter("title");
        String content = req.getParameter("content");

        if (title == null || content == null) {
            resp.sendError(400, "Missing fields");
            return;
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            PreparedStatement ps = conn.prepareStatement(
                "INSERT INTO reports (title, author, content, tenant_id, created_at) VALUES (?, ?, ?, ?, NOW())"
            );
            ps.setString(1, title);
            ps.setString(2, (String) req.getAttribute("x-user-name"));
            ps.setString(3, content);
            ps.setString(4, getTenantId(req));
            ps.executeUpdate();
            resp.setStatus(201);
        } catch (SQLException e) {
            resp.sendError(500, "Database error");
        }
    }
}
